<script lang="ts">
  import {onMount} from 'svelte';
  import type {NetworkApi,NetworkSnapshot} from '../api/networkMonitor';
  import type {HostApi} from '../api/hostMonitor';
  import type {NetworkDetails} from '../api/automation';
  import type {ScanStatus} from '../api/networkScan';
  import type {LiveState} from '../stores/live';
  import {networkInventory,responseLabel} from '../networkInventory';
  import {deviceIpSortKey,compareIpKeys} from '../ipSort';
  import {trafficPath,trafficCsv} from '../trafficFormat';
  import {formatThroughput} from './networkFormat';
  import TrafficView from './TrafficView.svelte';
  import Icon from './Icon.svelte';
  let {api,hostApi,liveState,network=null,scan=null,onselectdevice}:{api:NetworkApi;hostApi:HostApi;liveState:LiveState;network?:NetworkDetails|null;scan?:ScanStatus|null;onselectdevice:(id:string)=>void}=$props();
  let scope=$state<'network'|'computer'>('network');let snapshot=$state<NetworkSnapshot|null>(null);let error=$state('');let notice=$state('');let busy=$state(false);
  let query=$state('');let sort=$state('ip-asc');let minutes=$state(5);let paused=$state(false);let frozen=$state<NetworkSnapshot|null>(null);let setup=$state(false);
  let routerIp=$state('');let routerPort=$state(8080);let auto=$state(false);let interval=$state(120);let editing=false;
  let active=false;let generation=0;
  const inventory=$derived(networkInventory(liveState,network,snapshot,scan));
  const visible=$derived(inventory.filter(r=>`${r.name} ${r.kind} ${r.ips.join(' ')} ${r.macs.join(' ')} ${r.maker} ${r.room??''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='recent'?b.last.localeCompare(a.last):sort==='name'?a.name.localeCompare(b.name):compareIpKeys(deviceIpSortKey(a.ips),deviceIpSortKey(b.ips),sort==='ip-desc')||a.key.localeCompare(b.key)));
  const displayed=$derived(paused&&frozen?frozen:snapshot);
  const points=$derived(displayed?.points.map(p=>({at:p.at,received_bytes:p.download,sent_bytes:p.upload,measured_ms:1000}))??[]);
  const end=$derived(paused?(points.at(-1)?.at??Date.now()/1000):Math.max(points.at(-1)?.at??0,Date.now()/1000));const start=$derived(end-minutes*60);
  const max=$derived(Math.max(1,...points.flatMap(p=>[p.sent_bytes,p.received_bytes])));
  const responding=$derived(inventory.filter(r=>responseLabel(r.presence,snapshot?.settings.interval_seconds??120)==='Responding').length);
  const running=$derived(snapshot?.discovery.state==='running');
  async function refresh(){const key=++generation;try{const v=await api.snapshot(minutes);if(active&&key===generation){snapshot=v;error='';if(!editing){routerIp=v.settings.router_ip??'';routerPort=v.settings.router_port;auto=v.settings.discovery_enabled;interval=v.settings.interval_seconds;}}}catch(e){if(active&&key===generation){error=e instanceof Error?e.message:'Network monitoring is unavailable.';snapshot=null;}}}
  onMount(()=>{active=true;let timer:ReturnType<typeof setTimeout>;async function poll(){await refresh();if(active)timer=setTimeout(()=>void poll(),2000);}void poll();return()=>{active=false;generation++;clearTimeout(timer);};});
  $effect(()=>{minutes;if(active){paused=false;void refresh();}});
  async function discover(){busy=true;try{await api.discover();notice='Discovery started. Addresses outside the physical home network are excluded.';await refresh();}catch(e){notice=e instanceof Error?e.message:'Discovery could not start.';}finally{busy=false;}}
  async function cancel(){busy=true;try{await api.cancel();notice='Cancellation requested; waiting for the current OS probes to finish.';await refresh();}catch(e){notice=e instanceof Error?e.message:'Cancellation failed.';}finally{busy=false;}}
  async function save(){busy=true;try{await api.settings({router_ip:routerIp.trim()||null,router_port:routerPort,discovery_enabled:auto,interval_seconds:interval});editing=false;setup=false;notice='Network preferences saved. Waiting for fresh router readings.';await refresh();}catch(e){notice=e instanceof Error?e.message:'Preferences were not saved.';}finally{busy=false;}}
  function date(value:string){return new Date(value).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});}
  function exportCsv(){const data=trafficCsv([['Device','IP addresses','MAC addresses','Discovery response','First seen','Last seen','Per-device traffic'],...visible.map(r=>[r.name,r.ips.join(' | '),r.macs.join(' | '),responseLabel(r.presence,snapshot?.settings.interval_seconds??120),r.first,r.last,'Unavailable'])]);const url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='neonhearth-network-devices.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<div class="scope" role="group" aria-label="Traffic scope"><button class:active={scope==='network'} aria-pressed={scope==='network'} onclick={()=>scope='network'}>Entire network</button><button class:active={scope==='computer'} aria-pressed={scope==='computer'} onclick={()=>scope='computer'}>This computer · applications</button></div>
{#if scope==='computer'}<TrafficView api={hostApi}/>{:else}
<section class="network-traffic" aria-labelledby="network-traffic-heading">
  <div class="view-heading"><div><p class="kicker">TRAFFIC / ENTIRE NETWORK</p><h1 id="network-traffic-heading">Your whole home, connected.</h1><p class="muted">Every discovered device, with household internet traffic measured at your router.</p></div><button onclick={()=>{setup=!setup;editing=setup;}}>Network preferences</button></div>
  {#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status" class="notice">{notice}</p>{/if}
  <div class="metrics"><article><Icon name="down"/><span>Household download<strong>{formatThroughput(snapshot?.router.download)}</strong></span></article><article><Icon name="up"/><span>Household upload<strong>{formatThroughput(snapshot?.router.upload)}</strong></span></article><article><Icon name="devices"/><span>Devices in inventory<strong>{inventory.length}</strong></span></article><article><Icon name="router"/><span>Connected · router report<strong>{snapshot?.router.connected_devices??'Unavailable'}</strong></span></article></div>
  {#if setup}<form class="preferences" onsubmit={e=>{e.preventDefault();void save();}}><h2>Home network collection</h2><p>Predator Connect W6: read its live WAN feed. This connection does not change router settings.</p><label>Router IPv4 address<input bind:value={routerIp} placeholder="192.168.1.1" maxlength="15"/></label><label>Router web port<input type="number" min="1" max="65535" bind:value={routerPort} required/></label><p>Leave the address blank to disconnect. Local LAN transfers and individual device byte counts are not included in the W6 WAN feed.</p><label><input type="checkbox" bind:checked={auto}/>Automatically discover devices</label><label>Discovery interval<select bind:value={interval}><option value={60}>Every minute</option><option value={120}>Every 2 minutes</option><option value={300}>Every 5 minutes</option><option value={900}>Every 15 minutes</option></select></label><button disabled={busy}>Save network preferences</button></form>{/if}
  <div class="chart-controls"><label>Time range<select bind:value={minutes}><option value={5}>5 minutes</option><option value={60}>1 hour</option><option value={1440}>24 hours</option></select></label><span class="source">Predator Connect W6 · WAN / internet · {snapshot?.router.status.replaceAll('_',' ')??'waiting'}</span><button onclick={()=>{if(paused){paused=false;frozen=null;}else{frozen=snapshot;paused=true;}}} aria-pressed={paused}>{paused?'Resume graph':'Pause graph'}</button></div>
  <div class="chart"><div class="scale">{formatThroughput(max)} <span>Download <i></i> Upload <i class="upload-key"></i></span></div>{#if points.length}<svg viewBox="0 0 900 200" role="img" aria-label="Entire household internet upload and download measured by the W6 router"><path class="grid" d="M0 20H900M0 60H900M0 100H900M0 140H900M0 180H900"/><path class="download" d={trafficPath(points,'received_bytes',start,end,max,(displayed?.bucket_seconds??2)*2)}/><path class="upload" d={trafficPath(points,'sent_bytes',start,end,max,(displayed?.bucket_seconds??2)*2)}/>{#each points as point}<circle cx={(point.at-start)/Math.max(1,end-start)*900} cy={180-point.received_bytes/max*160} r="2"><title>{date(new Date(point.at*1000).toISOString())} · Download {formatThroughput(point.received_bytes)} · Upload {formatThroughput(point.sent_bytes)}</title></circle>{/each}</svg>{:else}<div class="empty"><Icon name="pulse" size={40}/><strong>Waiting for your router's traffic feed</strong><p>Connect your W6 in Network preferences to see household internet use. The device inventory is available below.</p></div>{/if}<p class="coverage">Router-reported rates for the entire household. Gaps mean missing readings. Individual device usage requires a source with per-device counters.</p></div>
  <div class="discovery"><div><h2>Discover every device</h2><p>{responding} responding · {snapshot?.discovery.state.replaceAll('_',' ')??'waiting'}{running?` · ${snapshot?.discovery.completed} / ${snapshot?.discovery.total} addresses checked`:''}</p></div><button disabled={busy||running} onclick={discover}>Discover devices now</button>{#if running}<button disabled={busy} onclick={cancel}>Cancel discovery</button>{/if}</div>
  {#if snapshot?.discovery.finished_at}<p class="coverage">Last sweep {date(snapshot.discovery.finished_at)} · {snapshot.discovery.responding} responses · {snapshot.discovery.errors} probe errors{snapshot.discovery.skipped_networks?` · ${snapshot.discovery.skipped_networks} subnets excluded by scan limits`:''}. IPv4 discovery covers eligible physical LANs up to 1,024 addresses; IPv6 remains passively observed.</p>{/if}
  <div class="inventory-controls"><label>Search all devices<input bind:value={query} placeholder="Name, IP, MAC, manufacturer, or room"/></label><label>Sort devices<select bind:value={sort}><option value="ip-asc">IP address: low to high</option><option value="ip-desc">IP address: high to low</option><option value="name">Device name</option><option value="recent">Most recently seen</option></select></label><button onclick={exportCsv}>Export devices</button></div>
  <div class="device-list">{#each visible as row (row.key)}<article class="network-device"><div class="device-title"><Icon name={row.icon} size={26}/><div><strong>{row.name}</strong><span>{row.kind}{row.room?` · ${row.room}`:''}</span></div><span class="response" class:responding={responseLabel(row.presence,snapshot?.settings.interval_seconds??120)==='Responding'}>{responseLabel(row.presence,snapshot?.settings.interval_seconds??120)}</span></div><div class="device-facts"><p><b>IP address</b>{row.ips.join(' · ')||'Not currently observed'}</p><p><b>MAC address</b>{row.macs.join(' · ')||'Unavailable'}</p><p><b>Traffic for this device</b>Unavailable · no per-device counter source</p><p><b>First seen</b>{date(row.first)}</p><p><b>Last seen</b>{date(row.last)}</p>{#if row.maker}<p><b>Interface manufacturer</b>{row.maker}</p>{/if}</div>{#if row.device}<button onclick={()=>onselectdevice(row.device!.device_id)}>Device details & controls</button>{:else}<small>Discovered by an active LAN response. Waiting for its identity record.</small>{/if}</article>{:else}<p>No devices match this view. Start discovery to find devices on the physical home network.</p>{/each}</div>
  <details class="activity"><summary>Device discovery activity · {snapshot?.events.length??0} recent events</summary><p>“Not responding” means two completed sweeps received no response. A sleeping or isolated device may still be connected.</p>{#each snapshot?.events??[] as event}<article><strong>{event.kind==='discovered'?'New device discovered':event.kind==='responding_again'?'Device responding again':'Device not responding'}</strong><span>{event.ip} · {event.mac}</span><time>{date(event.at)}</time></article>{/each}</details>
</section>{/if}
<style>
  button,input,select{font:inherit;color:var(--ink)}button{min-height:40px;padding:9px 14px;border:1px solid var(--line-strong);border-radius:7px;background:linear-gradient(180deg,#17323be0,#102028e8);font-size:12px;cursor:pointer;transition:border-color .15s,background .15s}button:hover:not(:disabled){border-color:var(--accent);background:#193d46}button:disabled{opacity:.5;cursor:wait}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}input:not([type=checkbox]),select{min-height:40px;padding:9px 11px;border:1px solid var(--line-strong);border-radius:7px;background:#0c1c24;font-size:12px;color-scheme:dark;min-width:0}input::placeholder{color:var(--muted-strong)}input[type=checkbox]{width:18px;height:18px;accent-color:var(--accent)}.view-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.view-heading>div{flex:1 1 620px;min-width:0}.scope{padding:4px;border:1px solid var(--line-mid);border-radius:10px;width:fit-content;max-width:100%;background:#0b1a22aa}.scope button{background:transparent;border-color:transparent}.scope button.active{background:#16343e;border-color:var(--accent)}
  .scope{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}.scope .active{border-color:var(--accent);color:var(--accent);background:var(--accent-dim)}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.metrics article{display:flex;gap:12px;padding:20px 12px;border:1px solid var(--line-mid);border-radius:10px;background:var(--surface)}.metrics span{font-size:11px;color:var(--muted-strong)}.metrics strong{display:block;font:600 24px var(--font-display);color:var(--ink);margin-top:9px;overflow-wrap:anywhere}.view-heading{gap:15px;flex-wrap:wrap}.chart-controls,.inventory-controls,.discovery{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:22px 0}.chart-controls label,.inventory-controls label,.preferences label{display:grid;gap:7px;font-size:12px}.inventory-controls label:first-child{flex:1;min-width:180px}.source{flex:1;font-size:11px;color:var(--muted-strong);align-self:center}.chart,.preferences{background:radial-gradient(ellipse at 50% 100%,#123c4855,transparent 65%),var(--surface);border:1px solid var(--line-mid);padding:18px;border-radius:12px}.scale{display:flex;justify-content:space-between;font:11px var(--font-mono);gap:10px}.scale span{display:flex;align-items:center;gap:8px}.scale i{width:12px;height:3px;background:var(--accent)}.scale .upload-key{background:var(--gold)}svg{display:block;width:100%;min-height:150px}.grid{stroke:var(--line);stroke-dasharray:4 6;fill:none}.download,.upload{fill:none;stroke:var(--accent);stroke-width:2}.upload{stroke:var(--gold)}circle{fill:var(--accent)}.coverage{font-size:12px;line-height:1.6;color:var(--muted-strong)}.empty{min-height:220px;display:grid;align-content:center;justify-items:center;text-align:center;gap:12px}.empty p{max-width:510px;font-size:13px;line-height:1.6}.discovery{align-items:center}.discovery>div{flex:1}.discovery h2{font-size:20px;margin:0 0 8px}.discovery p{font-size:12px;color:var(--muted-strong);margin:0}.device-list{display:grid;gap:12px}.network-device{padding:20px;border:1px solid var(--line-mid);background:var(--surface);border-radius:10px;min-width:0}.device-title{display:flex;align-items:center;gap:12px}.device-title>div{flex:1;min-width:0;overflow-wrap:anywhere}.device-title strong{font-size:16px}.device-title div span{display:block;font-size:11px;color:var(--muted-strong);margin-top:6px}.response{font-size:11px;color:var(--muted-strong)}.responding{color:var(--accent)}.device-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px 14px;margin:12px 0}.device-facts p{font:12px var(--font-mono);line-height:1.7;overflow-wrap:anywhere}.device-facts b{display:block;font-size:10px;color:var(--muted-strong);text-transform:uppercase;margin-bottom:5px}.network-device small{font-size:12px;color:var(--muted-strong)}.activity{margin-top:25px;border-top:1px solid var(--line-mid);padding-top:18px}.activity summary{cursor:pointer}.activity p{font-size:12px;line-height:1.6}.activity article{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;font-size:12px;padding:12px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}.activity time{color:var(--muted-strong)}.notice{padding:12px;border:1px solid var(--line-strong);border-radius:8px;font-size:13px}.preferences{display:grid;gap:14px;margin:20px 0}.preferences h2{margin:0}.preferences p{font-size:13px;line-height:1.6;margin:0}.preferences label:has(input[type=checkbox]){display:flex;align-items:center}.preferences input,.preferences select{max-width:100%}.preferences button{justify-self:start}@media(max-width:1100px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.device-facts{grid-template-columns:repeat(2,minmax(0,1fr))}.activity article{grid-template-columns:1fr}}@media(max-width:650px){.metrics strong{font-size:18px}.device-facts{grid-template-columns:1fr}.device-title{flex-wrap:wrap}.response{width:100%;padding-left:38px}.network-device{padding:16px}.inventory-controls label{width:100%}.inventory-controls input,.inventory-controls select{max-width:100%}.chart{padding:12px}.scale{font-size:10px}}
</style>
